files.content:
/* Palette: #f4f1de (bg), #e07a5f (accent), #3d405b (text), #81b29a (available), #f2cc8f (checked out) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #f4f1de;
  color: #3d405b;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: #fff;
  border-radius: 1rem;
  box-shadow: 0 8px 24px rgba(61, 64, 91, 0.15);
  max-width: 640px;
  width: 100%;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: #3d405b;
}

.subtitle {
  color: #6b7280;
  font-size: 1rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem;
  background: #f9f7f3;
  border-radius: 0.75rem;
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  font-weight: 500;
  user-select: none;
}

.filter-label input[type="checkbox"] {
  width: 1.25rem;
  height: 1.25rem;
  accent-color: #e07a5f;
  cursor: pointer;
}

.filter-label input[type="checkbox"]:focus-visible {
  outline: 3px solid #e07a5f;
  outline-offset: 2px;
  border-radius: 4px;
}

.count {
  font-weight: 600;
  color: #e07a5f;
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 1rem;
  border-radius: 0.75rem;
  background: #f9f7f3;
  border-left: 4px solid #81b29a;
  transition: background 0.2s;
}

.book-item.checked-out {
  border-left-color: #f2cc8f;
  background: #fef9f0;
}

.book-info {
  flex: 1 1 200px;
  min-width: 0;
}

.book-title {
  font-weight: 600;
  font-size: 1.05rem;
  word-break: break-word;
}

.book-author {
  font-size: 0.9rem;
  color: #6b7280;
}

.book-status {
  font-size: 0.85rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  white-space: nowrap;
}

.book-status.available {
  background: #d1e7dd;
  color: #0f5132;
}

.book-status.checked-out {
  background: #fff3cd;
  color: #664d03;
}

.btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 3px solid #e07a5f;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn-checkout {
  background: #e07a5f;
  color: #fff;
}

.btn-checkout:hover {
  background: #c9654a;
}

.btn-return {
  background: #81b29a;
  color: #fff;
}

.btn-return:hover {
  background: #6a9b82;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.footer {
  text-align: center;
  font-size: 0.85rem;
  color: #9ca3af;
  padding-top: 0.5rem;
  border-top: 1px solid #e5e7eb;
}

[hidden] {
  display: none !important;
}

@media (max-width: 480px) {
  .card {
    padding: 1.25rem;
  }
  .header h1 {
    font-size: 1.4rem;
  }
  .book-item {
    flex-direction: column;
    align-items: stretch;
  }
  .btn {
    width: 100%;
  }
}

const books = [
  { id: 1, title: 'The Pixel Garden', author: 'Ada Lovelace', checkedOut: false },
  { id: 2, title: 'CSS: The Definitive Guide', author: 'Eric Meyer', checkedOut: false },
  { id: 3, title: 'JavaScript: The Good Parts', author: 'Douglas Crockford', checkedOut: false },
  { id: 4, title: 'Designing Data-Intensive Applications', author: 'Martin Kleppmann', checkedOut: false },
  { id: 5, title: 'The Pragmatic Programmer', author: 'Andrew Hunt', checkedOut: false },
  { id: 6, title: 'Refactoring', author: 'Martin Fowler', checkedOut: false }
];

const bookList = document.getElementById('book-list');
const filterCheckbox = document.getElementById('filter-available');
const checkedOutCount = document.getElementById('checked-out-count');

function updateCount() {
  const count = books.filter(b => b.checkedOut).length;
  checkedOutCount.textContent = count;
}

function renderBooks() {
  const showAvailableOnly = filterCheckbox.checked;
  const filtered = showAvailableOnly ? books.filter(b => !b.checkedOut) : books;

  bookList.innerHTML = '';

  if (filtered.length === 0) {
    const empty = document.createElement('li');
    empty.className = 'book-item';
    empty.textContent = 'No available books at the moment.';
    bookList.appendChild(empty);
    updateCount();
    return;
  }

  filtered.forEach(book => {
    const li = document.createElement('li');
    li.className = `book-item ${book.checkedOut ? 'checked-out' : ''}`;

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('div');
    title.className = 'book-title';
    title.textContent = book.title;

    const author = document.createElement('div');
    author.className = 'book-author';
    author.textContent = `by ${book.author}`;

    info.appendChild(title);
    info.appendChild(author);

    const status = document.createElement('span');
    status.className = `book-status ${book.checkedOut ? 'checked-out' : 'available'}`;
    status.textContent = book.checkedOut ? 'Checked out' : 'Available';

    const btn = document.createElement('button');
    btn.className = `btn ${book.checkedOut ? 'btn-return' : 'btn-checkout'}`;
    btn.textContent = book.checkedOut ? 'Return' : 'Check out';
    btn.setAttribute('aria-label', `${book.checkedOut ? 'Return' : 'Check out'} ${book.title}`);

    btn.addEventListener('click', () => {
      book.checkedOut = !book.checkedOut;
      renderBooks();
    });

    li.appendChild(info);
    li.appendChild(status);
    li.appendChild(btn);
    bookList.appendChild(li);
  });

  updateCount();
}

filterCheckbox.addEventListener('change', renderBooks);

renderBooks();
